import pandas as pd# --- 1. Read in the dataset ---df = pd.read_excel("matches.xlsx")# --- 2. Drop any rows where 'File Count' is less than 4 ---df = df[df["File Count"] >= 4].copy()# --- 3. Make separate groups of files by year ---# 'Published Date' looks like '2021-05-13', so we extract the year from it.df["Year"] = pd.to_datetime(df["Published Date"]).dt.year# groupby object: lets you loop over (year, sub-dataframe) pairsgroups_by_year = df.groupby("Year")# Option A: dict of {year: dataframe} for direct indexing, e.g. yearly_data[2023]yearly_data = {year: group for year, group in groups_by_year}# Example usage:for year, group_df in yearly_data.items():    print(f"Year {year}: {len(group_df)} rows")# --- 4. Take a random 10% sample of rows within each year group ---# random_state fixes the seed so results are reproducible; drop it (or change it) for a different sample each run.sampled_by_year = {    year: group_df.sample(frac=0.10, random_state=42)    for year, group_df in yearly_data.items()}for year, sample_df in sampled_by_year.items():    print(f"Year {year}: sampled {len(sample_df)} of {len(yearly_data[year])} rows")# --- 5. Save each year's sample as its own file: '{year}_randomsample.xlsx' ---for year, sample_df in sampled_by_year.items():    sample_df.to_excel(f"{year}_randomsample.xlsx", index=False)